/* ── Filtros de Itens ── */
let _fitMain  = 'todas';
let _fitArmaT = 'todas';  // fogo | branca | todas
let _fitArmaPeso  = 'todas';  // leve | media | pesada | todas
let _fitArmaAlc   = 'todas';  // curto | medio | longo | corpo | todas

function _setActiveBtns(selector, activeId){
  document.querySelectorAll(selector).forEach(b=>{
    b.style.background = b.id===activeId ? 'rgba(195,4,13,0.2)' : 'transparent';
  });
}

function setFiltroMain(tipo){
  _fitMain = tipo;
  _fitArmaT = 'todas'; _fitArmaPeso = 'todas'; _fitArmaAlc = 'todas';
  // Update chip active state
  document.querySelectorAll('.fit-chip').forEach(b=>{
    b.classList.toggle('active', b.id === 'fit-'+tipo);
  });
  // Mostrar/ocultar subfiltros de arma
  const sf = document.getElementById('itens-subfiltros-arma');
  if(sf) sf.style.display = tipo==='arma' ? 'block' : 'none';
  // Reset subfiltros visuais
  document.querySelectorAll('.fit-chip2').forEach(b=> b.style.background='transparent');
  const defaults = {'.fit-chip2':'fsub-arma-todas'};
  ['fsub-arma-todas','fsub-peso-todas','fsub-alc-todas'].forEach(id=>{
    const el=document.getElementById(id);
    if(el) el.style.background='rgba(129,15,15,0.2)';
  });
  // Fechar detalhe e limpar seleção
  const dp=document.getElementById('item-detail-panel');
  if(dp) dp.style.display='none';
  _invItemSelecionado=null;
  const addBtn=document.getElementById('btn-add-to-inv');
  if(addBtn) addBtn.style.display='none';
  renderItens();
}

function setFiltroSub(dim, val){
  const idMap = {'arma-tipo':'fsub-arma-', 'arma-peso':'fsub-peso-', 'arma-alcance':'fsub-alc-'};
  if(dim==='arma-tipo')   _fitArmaT=val;
  if(dim==='arma-peso')   _fitArmaPeso=val;
  if(dim==='arma-alcance')_fitArmaAlc=val;
  // Highlight activo no grupo correto
  const prefix = idMap[dim];
  if(prefix){
    document.querySelectorAll('.fit-chip2').forEach(b=>{
      if(b.id && b.id.startsWith(prefix)){
        b.style.background = b.id===prefix+val ? 'rgba(195,4,13,0.2)' : 'transparent';
      }
    });
  }
  renderItens();
}

// Compatibilidade com código legado
function filtrarItens(tipo){ setFiltroMain(tipo||'todas'); }

/* Cores por tipo */
const _CT_ITENS = {
  arma:'#ee3000', armadura:'#0d8cf2', 'item-comum':'#91c32b',
  equipamento:'#7777dd', paranormal:'#c8a000',
  veiculo:'#3c6fd4', modificacao:'#b24de6', explosivo:'#ff6600',
  protecao:'#0d8cf2'  // alias legado
};
/* Labels por tipo */
const _LBL_ITENS = {
  arma:'ARMA', armadura:'ARMADURA', 'item-comum':'ITEM COMUM',
  equipamento:'EQUIP.', paranormal:'PARANORMAL',
  veiculo:'VEÍCULO', modificacao:'MODIFICAÇÃO', explosivo:'EXPLOSIVO', protecao:'ARMADURA'
};
/* Labels para tipoDano */
const _LBL_TIPO_DANO = { B:'Balístico', F:'Físico', C:'Cortante', P:'Perfurante', I:'Impacto',
  Fogo:'Fogo', E:'Energia', M:'Morte', S:'Sangue', K:'Conhecimento', Me:'Medo' };

function renderItens(){
  const g=document.getElementById('itens-grid'); if(!g) return;
  const busca=(document.getElementById('itens-busca')||{}).value||'';
  const cf=(document.getElementById('itens-categoria-fil')||{}).value||'';

  let l = _fitMain==='todas' ? ITENS_DB : ITENS_DB.filter(i=>{
    const t = i.tipo==='protecao' ? 'armadura' : i.tipo;
    return t===_fitMain;
  });
  if(_fitMain==='arma'){
    if(_fitArmaT!=='todas')    l=l.filter(i=>i.subTipo===_fitArmaT);
    if(_fitArmaPeso!=='todas') l=l.filter(i=>(i.peso||'').toLowerCase()===_fitArmaPeso);
    if(_fitArmaAlc!=='todas'){
      if(_fitArmaAlc==='corpo') l=l.filter(i=>!i.alcance);
      else l=l.filter(i=>(i.alcance||'').toLowerCase().includes(_fitArmaAlc));
    }
  }
  if(busca) l=l.filter(i=>i.nome.toLowerCase().includes(busca.toLowerCase())||(i.desc||'').toLowerCase().includes(busca.toLowerCase()));
  if(cf) l=l.filter(i=>String(i.cat)===cf);

  if(!l.length){
    g.innerHTML='<div style="color:var(--white-dust);font-size:12px;font-family:\'Courier Prime\',monospace;text-align:center;padding:24px 0">Nenhum item encontrado.</div>';
    return;
  }

  // Renderiza como lista de linhas compactas, 1 coluna
  g.innerHTML = l.map(i=>{
    const tipo_real = i.tipo==='protecao'?'armadura':i.tipo;
    const cor  = _CT_ITENS[tipo_real]||'#888';
    const lbl  = _LBL_ITENS[tipo_real]||tipo_real.toUpperCase();
    const td   = i.tipoDano ? TIPOS_DANO[i.tipoDano] : null;

    let statsHtml = '';
    if(i.dam)    statsHtml+=`<span>⚄ <b style="color:${td?.cor||'#ee3000'}">${i.dam}</b></span>`;
    if(i.area)   statsHtml+=`<span style="color:#ff8844">✷ ${i.area}</span>`;
    if(i.alcance)statsHtml+=`<span>↔ ${i.alcance}</span>`;
    if(i.defesa) statsHtml+=`<span>🛡 <b style="color:#3af">${i.defesa}</b></span>`;
    if(i.rd)     statsHtml+=`<span>RD <b style="color:#3af">${i.rd}</b></span>`;
    if(i.peso)   statsHtml+=`<span style="color:#666">[${i.peso}]</span>`;

    return `<div onclick="verItem('${i.id}')" data-item-id="${i.id}"
      style="border-left:2px solid ${cor};border-bottom:1px solid rgba(19,14,13,0.4);padding:8px 10px 8px 12px;cursor:pointer;display:flex;align-items:center;gap:10px;transition:background .1s"
      onmouseover="this.style.background='rgba(19,16,14,0.7)'" onmouseout="this.style.background='transparent'">
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:${statsHtml?'3px':'0'}">
          <span style="font-family:'Cinzel',serif;font-size:12px;color:var(--white-bone)">${i.nome}</span>
          <span style="font-size:9px;color:var(--gold-light);font-family:'Courier Prime',monospace;flex-shrink:0">C${i.cat}</span>
        </div>
        ${statsHtml?`<div style="display:flex;gap:8px;flex-wrap:wrap;font-size:10px;font-family:'Courier Prime',monospace;color:var(--white-dust)">${statsHtml}</div>`:''}
      </div>
      <div style="display:flex;align-items:center;gap:6px;flex-shrink:0">
        ${td?`<span style="font-size:11px;color:${td.cor}">${td.emoji}</span>`:''}
        <span style="font-size:9px;padding:1px 6px;border:1px solid ${cor};color:${cor};font-family:'Oswald',sans-serif">${lbl}</span>
        <button onclick="event.stopPropagation();addInvFromDB('${i.id}')"
          title="Adicionar à mochila"
          style="background:transparent;border:1px solid rgba(0,214,97,0.3);color:rgba(0,234,93,0.6);font-size:11px;cursor:pointer;padding:1px 6px;line-height:1.4"
          onmouseover="this.style.color='#00ee5f';this.style.borderColor='#00ee5f'" onmouseout="this.style.color='rgba(0,234,93,0.6)';this.style.borderColor='rgba(0,214,97,0.3)'">+</button>
      </div>
    </div>`;
  }).join('');
}

