/* ── Rolar dado de dano de ritual e exibir resultado ── */
function rolarDado(expr){
  // Suporta XdY+Z ou XdY-Z
  const m = String(expr).match(/^(\d+)d(\d+)([+-]\d+)?$/i);
  if(!m) return parseInt(expr)||0;
  const qtd  = parseInt(m[1]);
  const face = parseInt(m[2]);
  const mod  = parseInt(m[3]||0);
  let total  = mod;
  const rolls = [];
  for(let i=0;i<qtd;i++){
    const r = Math.floor(Math.random()*face)+1;
    rolls.push(r);
    total += r;
  }
  return { total: Math.max(0,total), rolls, expr };
}

function rolarDanoRitual(nomeRitual, damExpr, tipoDano){
  const td   = TIPOS_DANO[tipoDano];
  const cor  = td ? td.cor : '#ee3000';
  const result = rolarDado(damExpr);
  const total  = result.total || result;
  const rolls  = result.rolls || [];

  // Calcula RD da armadura equipada
  const c   = userChar(currentUser);
  const arm = c.armaduraEquipada ? ITENS_DB.find(i=>i.id===c.armaduraEquipada) : null;
  const rd  = calcularRD(arm, tipoDano);
  const danoFinal = Math.max(0, total - rd);

  // Mostra resultado no painel de dano da ficha, se estiver visível
  const el = document.getElementById('dmg-resultado');
  if(el){
    el.style.display='block';
    let html = `<div style="margin-bottom:6px;font-size:12px;color:${cor};font-family:'Cinzel',serif;letter-spacing:.06em">${td?td.emoji:''} ${nomeRitual} — Dano ${td?td.nome:tipoDano}</div>`;
    html += `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:6px;font-family:'Courier Prime',monospace;font-size:11px">`;
    if(rolls.length) html += `<span style="color:var(--white-dust)">Dados: [${rolls.join(', ')}]</span>`;
    html += `<span style="color:var(--white-dust)">→ Bruto: <b style="color:${cor}">${total}</b></span>`;
    if(rd>0) html += `<span style="color:var(--white-dust)">− RD <b style="color:#3af">${rd}</b></span>`;
    html += `<span style="color:var(--white-dust)">= Final: <b style="color:${danoFinal>0?cor:'#00ee5f'};font-size:14px">${danoFinal}</b></span>`;
    html += `</div>`;
    if(rd>0 && arm) html += `<div style="font-size:10px;color:#77aadd;font-family:'Courier Prime',monospace">🛡 ${arm.nome} absorveu ${rd} de dano ${td?td.nome:tipoDano}.</div>`;
    el.innerHTML = html;
  }

  // Loga no log de dados
  if(!db.rolls) db.rolls={};
  if(!db.rolls[currentUser]) db.rolls[currentUser]=[];
  const hora = new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
  db.rolls[currentUser].unshift({ h:hora, label:`[Ritual] ${nomeRitual}: ${damExpr} = ${total}${rd>0?` → ${danoFinal} (RD −${rd})`:''}`, ctx: td?`${td.emoji} ${td.nome}`:'', total: danoFinal });
  if(db.rolls[currentUser].length>50) db.rolls[currentUser].length=50;
  saveDB();
  renderLog();
  toast(`⚄ ${nomeRitual}: ${total} de dano${rd>0?` (−${rd} RD = ${danoFinal}`+' final)':''}`);
}


