function renderElementos(){
  const g = document.getElementById('elementos-grid');
  if(!g) return;
  g.innerHTML = ELEMENTOS.map(el=>`
    <div onclick="verElemento('${el.id}')" style="background:rgba(19,16,12,0.9);border:1px solid ${el.cor};padding:16px;cursor:pointer;transition:all .2s;position:relative;overflow:hidden">
      <div style="position:absolute;top:0;left:0;right:0;height:2px;background:${el.cor};opacity:.7"></div>
      <div class="sym-el ${el.id==='sangue'?'sym-sangue':el.id==='morte'?'sym-morte':el.id==='energia'?'sym-energia':el.id==='conhecimento'?'sym-conhecimento':'sym-medo'}" style="display:block;width:100%;height:110px;background-size:contain;background-position:center;opacity:0.75;margin-bottom:10px"></div>
      <div style="font-family:'Cinzel',serif;font-size:13px;letter-spacing:.12em;color:${el.cor};text-transform:uppercase;margin-bottom:6px">${el.nome}</div>
      <div style="font-size:12px;color:var(--white-dust);line-height:1.6;font-family:'Courier Prime',monospace">${el.desc.substring(0,80)}…</div>
      <div style="margin-top:10px;font-size:10px;letter-spacing:.1em;color:var(--white-dust);font-family:'Oswald',sans-serif">VER DETALHES →</div>
    </div>`).join('');
}

/* Abre a descrição do item/ritual selecionado no painel de ação do Inventário, em popup */
function _verDescInvAction(){
  const d = window._invActionAtualDesc; if(!d) return;
  let corpo = d.desc || '';
  if(d.habs?.length){
    corpo += d.habs.map(h=>`<br><br><b style="color:var(--gold-light)">${h.nome}</b><br>${h.desc}`).join('');
  }
  if(d.disc && d.disc!=='—') corpo += `<br><br><b style="color:#33b2ff">DISCENTE</b><br>${d.disc}`;
  if(d.verd && d.verd!=='—') corpo += `<br><br><b style="color:var(--gold-light)">VERDADEIRO</b><br>${d.verd}`;
  abrirDescPopup(d.nome, corpo);
}

function verElemento(id){
  const el = ELEMENTOS.find(e=>e.id===id);
  if(!el) return;
  const p = document.getElementById('el-detail-panel');
  abrirModalDetalhe(`
    <div style="color:${el.cor};display:flex;align-items:center;gap:10px;font-family:'Cinzel',serif;font-size:17px;margin-bottom:14px"><span class="sym-el sym-elem-icon ${el.id==='sangue'?'sym-sangue':el.id==='morte'?'sym-morte':el.id==='energia'?'sym-energia':el.id==='conhecimento'?'sym-conhecimento':'sym-medo'}"></span>${el.nome}</div>
    <p style="font-family:'IM Fell English',serif;font-style:italic;color:var(--white-ash);font-size:17px;margin-bottom:14px;line-height:1.85">${el.desc}</p>
    <div style="margin-bottom:12px">
      <div style="font-family:'Cinzel',serif;font-size:10px;letter-spacing:.15em;color:${el.cor};text-transform:uppercase;margin-bottom:8px">Efeitos Conhecidos</div>
      ${el.efeitos.map(e=>`<div style="display:flex;gap:8px;padding:6px 0;border-bottom:1px solid var(--blood-deep);font-size:15px;line-height:1.5;color:var(--white-bone);font-family:'Courier Prime',monospace"><span style="color:${el.cor};flex-shrink:0">▸</span>${e}</div>`).join('')}
    </div>
    <div style="background:rgba(195,4,13,0.08);border:1px solid var(--blood-deep);padding:10px 14px;font-size:14px;line-height:1.6;font-family:'Courier Prime',monospace;color:#e64d4d">
      <span style="font-family:'Cinzel',serif;font-size:10px;letter-spacing:.12em;color:var(--crimson)">CUSTO ⚠ </span>${el.custo}
    </div>`);
}


