function _jaTranscendeu() {
  const c = userChar(currentUser);
  return !!(c.transcendencia && c.transcendencia.elemento);
}

function _getRituaisDesbloqueados(nex) {
  if (nex < 5)  return 0;
  if (nex < 15) return 2;
  if (nex < 25) return 4;
  if (nex < 50) return 7;
  if (nex < 75) return 12;
  return 999;
}

